fetch dt.system.events, scanLimitGBytes: -1
| filter event.type == "AppEngine Functions - Small"
| filter event.kind == "BILLING_USAGE_EVENT"
| filter (billing_type == "BILLABLE" OR isNull(billing_type))
| summarize {
    billed_invocations = takeAny(billed_invocations)
  }, by: {
    startHour = bin(timestamp, 1h),
    event.id,
    user.email,
    caller.app.id
  }
| summarize {
    Invocations = sum( if( billed_invocations, billed_invocations, else:1 ))
  }, by: {
    { user.email, alias:User },
    { caller.app.id, alias:Calling_App }
  }
| sort Invocations desc
| summarize sum(Invocations), by:{Calling_App, User}

