fetch dt.system.events
| filter event.kind == "BILLING_USAGE_EVENT"
| filter event.type == "Events - Query" or event.type == "Events - Query - SaaS"
| fieldsAdd query_id = if(event.version == "1.0", event.id, else: query_id)
| dedup event.id
| summarize {
   data_read_bytes = toDouble(sum(billed_bytes)),
   Query_count = countDistinctExact(query_id)
  }, by: {
   App_context = client.application_context, application_detail = client.source, User = user.email
  }

| fieldsAdd split_by_application_detail = record(data_read_bytes, App_context, application_detail, User, Query_count)
| summarize {
    split_by_application_detail = arraySort(collectArray(split_by_application_detail), direction: "descending"),
    data_read_bytes = sum(data_read_bytes),
    Query_count = sum(Query_count)
}, by:{
    User, App_context
}
| fieldsAdd split_by_application_detail = record(User = split_by_application_detail[][User], App_context = split_by_application_detail[][App_context], application_detail = split_by_application_detail[][application_detail], data_read_bytes = split_by_application_detail[][data_read_bytes], data_read_pct = (split_by_application_detail[][data_read_bytes] / data_read_bytes * 100), Query_count = split_by_application_detail[][Query_count])
| fieldsAdd split_by_application_detail = if(arraySize(split_by_application_detail) == 1, arrayFirst(split_by_application_detail)[application_detail], else: split_by_application_detail)

| fieldsAdd App_contexts = record(data_read_bytes, User, App_context, split_by_application_detail, Query_count)
| summarize {
   App_contexts = arraySort(collectArray(App_contexts), direction: "descending"),
   data_read_bytes = sum(data_read_bytes),
   Query_count = toLong(sum(Query_count))
}, by:{
   User
}
| fieldsAdd App_contexts = record(User = App_contexts[][User], App_context = App_contexts[][App_context], split_by_application_detail = App_contexts[][split_by_application_detail], data_read_bytes = App_contexts[][data_read_bytes], data_read_pct = App_contexts[][data_read_bytes] / data_read_bytes * 100, Query_count = App_contexts[][Query_count])

| fieldsAdd key = 1
| fieldsAdd total = lookup([
    fetch dt.system.events
    | filter event.kind == "BILLING_USAGE_EVENT" and (event.type == "Events - Query" or event.type == "Events - Query - SaaS")
    | dedup event.id
    | summarize total = sum(billed_bytes)
    | fieldsAdd key = 1
  ], sourceField: key, lookupField:key)[total]
| fields User, App_contexts, data_read_bytes, data_read_pct = data_read_bytes / total * 100, Query_count
| sort data_read_bytes desc

fetch dt.system.events
| filter event.kind == "BILLING_USAGE_EVENT" and event.type == "Events - Retain"
| summarize {usage.bucket = takeLast(coalesce(usage.bucket, usage.event_bucket)), billed_bytes = takeLast(billed_bytes)}, by:{billing_period = bin(timestamp, 1h), event.id}
| fields billing_period, billed_bytes, usage.bucket
| summarize sum(billed_bytes), by:{usage.bucket}

fetch dt.system.events
| filter event.kind == "BILLING_USAGE_EVENT" and event.type == "Full-Stack Monitoring"
| dedup event.id
| summarize billed_gibibyte = sum(billed_gibibyte_hours), by:{dt.entity.host}
| fields host_id = dt.entity.host, host_name = entityAttr(dt.entity.host, "entity.name"), billed_gibibyte
| lookup [fetch dt.entity.host ], sourceField:host_name, lookupField:entity.name
| expand lookup.dt.security_context
| summarize count = count(), by:{lookup.dt.security_context, billed_gibibyte}
| fieldsAdd totalCost = (billed_gibibyte) * 0.04, {count, alias:hostCount}
| sort billed_gibibyte DESC

