| fieldsAdd App_contexts = record(User = App_contexts[][User], App_context = App_contexts[][App_context], split_by_application_detail = App_contexts[][split_by_application_detail], data_read_bytes = App_contexts[][data_read_bytes], data_read_pct = App_contexts[][data_read_bytes] / data_read_bytes * 100, Query_count = App_contexts[][Query_count])

| fieldsAdd key = 1
| fieldsAdd total = lookup([
    fetch dt.system.events
    | filter event.kind == "BILLING_USAGE_EVENT" and event.type == "Traces - Query"
    | dedup event.id
    | summarize total = sum(billed_bytes)
    | fieldsAdd key = 1
  ], sourceField: key, lookupField:key)[total]

| fields User, App_contexts, data_read_bytes, data_read_pct = data_read_bytes / total * 100, Query_count
| sort data_read_bytes desc
| expand App_contexts
| fieldsAdd App_context = App_contexts[App_context]
| fields User, App_context, data_read_bytes, data_read_pct, Query_count

fetch dt.system.events
| filter event.kind == "BILLING_USAGE_EVENT" and event.type == "Traces - Retain"
| summarize {usage.bucket = takeLast(coalesce(usage.bucket, usage.event_bucket)), billed_bytes = takeLast(billed_bytes)}, by:{billing_period = bin(timestamp, 1h), event.id}
| fields billing_period, billed_bytes, usage.bucket
| summarize sum(billed_bytes), by:{usage.bucket}
